logger = logging.getLogger(__name__)

_FLAT_BLOCK = 4096
# Larger DMA granularity pays off only while the three-buffer working set still
# fits in the device L2 (fp16/bf16 tensors around 16M elements); HBM-saturated
# shapes prefer the smaller tile because it keeps more requests outstanding.
_BLOCK_LARGE = 8192
_LARGE_LO = 1 << 20
_LARGE_HI = 1 << 25
_FLAT_WARPS = 1
_STRIDED_BLOCK = 1024
_MAX_RANK = 8


@triton.jit
def _div_flat_kernel(
    x_ptr,
    y_ptr,
    o_ptr,
    n,
    xs,
    ys,
    SX: tl.constexpr,
    SY: tl.constexpr,
    HALF: tl.constexpr,
    EVEN: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        # n is an exact multiple of BLOCK: every program is fully in range, so the
        # mask compare and the predicated vector load/store can be dropped.
        if SX:
            xf = xs
        else:
            xf = tl.load(x_ptr + offs)
        if SY:
            yf = ys
        else:
            yf = tl.load(y_ptr + offs)
        if HALF:
            r = xf / yf
        else:
            r = xf.to(tl.float32) / yf.to(tl.float32)
        tl.store(o_ptr + offs, r.to(o_ptr.dtype.element_ty))
    else:
        mask = offs < n
        if SX:
            xf = xs
        else:
            xf = tl.load(x_ptr + offs, mask=mask, other=0.0)
        if SY:
            yf = ys
        else:
            yf = tl.load(y_ptr + offs, mask=mask, other=0.0)
        if HALF:
            r = xf / yf
        else:
            r = xf.to(tl.float32) / yf.to(tl.float32)
        tl.store(o_ptr + offs, r.to(o_ptr.dtype.element_ty), mask=mask)


