def _out_dtype(a, b):
    if isinstance(b, torch.Tensor) and a.dtype is b.dtype:
        dt = a.dtype
    else:
        dt = torch.result_type(a, b)
    if not dt.is_floating_point and not dt.is_complex:
        dt = torch.get_default_dtype()
    return dt


def _launch_strided(a, b, xval, yval, out, shape, n):
    rank = len(shape)
    ost_full = out.stride()
    if a is not None:
        xst_full = a.stride() if a.shape == shape else a.expand(shape).stride()
    else:
        xst_full = None
    if b is not None:
        yst_full = b.stride() if b.shape == shape else b.expand(shape).stride()
    else:
        yst_full = None

    dims = []
    xst = []
    yst = []
    ost = []
    for d in range(rank):
        if shape[d] == 1:
            continue
        dims.append(shape[d])
        xst.append(0 if xst_full is None else xst_full[d])
        yst.append(0 if yst_full is None else yst_full[d])
        ost.append(ost_full[d])

    r = len(dims)
    if r > _MAX_RANK:
        raise RuntimeError("true_divide: collapsed rank exceeds supported maximum")
    pad = _MAX_RANK - r
    dims += [1] * pad
    xst += [0] * pad
    yst += [0] * pad
    ost += [0] * pad

    sx = xval is not None
    sy = yval is not None
    xp = out if a is None else a
    yp = out if b is None else b
    grid = ((n + _STRIDED_BLOCK - 1) // _STRIDED_BLOCK,)
    _div_strided_kernel[grid](
        xp,
        yp,
        out,
        n,
        *dims,
        *xst,
        *yst,
        *ost,
        0.0 if xval is None else xval,
        0.0 if yval is None else yval,
        sx,
        sy,
        r,
        BLOCK=_STRIDED_BLOCK,
        num_warps=1,
    )


